import pandas as pd
import re
import subprocess
import os
import json


class FSCtoDTConverter:
    def __init__(self, fsc_output, dtcontrol_path="dtcontrol"):
        """
        Initializes the converter with FSC output as a list of strings.
        """
        self.fsc_output = fsc_output.split(", ")
        self.dtcontrol_path = dtcontrol_path
        self.action_data = []  # To store (observations, m, A) tuples
        self.memory_data = []  # To store (observations, m, M') tuples
        self.observation_keys = set()  # To store all unique observation keys
        self.parse_fsc_output()

    def parse_fsc_output(self):
        """
        Parses the FSC output to extract action and memory transitions.
        Each line is wrapped in quotes and contains variable assignments.
        """
        action_pattern = re.compile(r"A\(\[(.+?)\],(\d+)\)=(\w+)")
        memory_pattern = re.compile(r"M\(\[(.+?)\],(\d+)\)=(\d+)")
        var_pattern = re.compile(r"(\w+)=(\d+|\w+)")

        for line in self.fsc_output:
            # Remove quotes and whitespace
            line = line.strip(' "')

            action_match = action_pattern.match(line)
            memory_match = memory_pattern.match(line)

            if action_match:
                vars_str, m, action = action_match.groups()
                # Parse variables into a dict
                vars_dict = dict(var_pattern.findall(vars_str))
                # Update observation keys
                self.observation_keys.update(vars_dict.keys())
                self.action_data.append((vars_dict, int(m), action))

            if memory_match:
                vars_str, m, new_m = memory_match.groups()
                # Parse variables into a dict
                vars_dict = dict(var_pattern.findall(vars_str))
                # Update observation keys
                self.observation_keys.update(vars_dict.keys())
                self.memory_data.append((vars_dict, int(m), int(new_m)))

    def get_action_dataframe(self):
        """
        Returns a DataFrame for action decision trees.
        """
        # Create DataFrame with all observation keys as columns
        df = pd.DataFrame(
            self.action_data, columns=["observations", "memory", "action"]
        )
        for key in self.observation_keys:
            df[key] = df["observations"].apply(lambda x: x.get(key, 0))
        df.drop(columns=["observations"], inplace=True)
        return df

    def get_memory_dataframe(self):
        """
        Returns a DataFrame for memory transition decision trees.
        """
        # Create DataFrame with all observation keys as columns
        df = pd.DataFrame(
            self.memory_data, columns=["observations", "memory", "next_memory"]
        )
        for key in self.observation_keys:
            df[key] = df["observations"].apply(lambda x: x.get(key, 0))
        df.drop(columns=["observations"], inplace=True)
        return df

    def save_csv_files(self, memory_value, base_dir="decision_trees"):
        """
        Saves DataFrames as CSV files and their metadata configs for a specific memory value.
        """
        # Create directory structure
        memory_dir = os.path.join(base_dir, f"memory_{memory_value}")
        os.makedirs(memory_dir, exist_ok=True)

        action_file = os.path.join(memory_dir, f"{memory_value}_action_data.csv")
        memory_file = os.path.join(memory_dir, f"{memory_value}_memory_data.csv")

        # Filter data for specific memory value
        action_df = self.get_action_dataframe()
        memory_df = self.get_memory_dataframe()

        action_df_filtered = action_df[action_df["memory"] == memory_value]
        memory_df_filtered = memory_df[memory_df["memory"] == memory_value]

        # Number of input variables is the number of unique observation keys
        num_inputs = len(self.observation_keys)
        x_column_names = sorted(list(self.observation_keys))

        # Create metadata configs for both action and memory files
        def create_config(df, target_column):
            """
            Creates configuration for decision tree data file.
            Treats boolean (0/1) values as categorical, other values as numeric.

            Args:
                df: DataFrame containing the data
                target_column: Name of the target column (action/next_memory)
            """
            numeric_cols = []
            categorical_cols = []
            x_category_names = {}
            all_columns = list(self.observation_keys)  # input columns only

            # First handle observation columns (input variables)
            for idx, col in enumerate(all_columns):
                unique_values = set(df[col].unique())
                # Treat boolean variables as categorical
                if unique_values <= {"0", "1"}:
                    categorical_cols.append(idx)
                    x_category_names[col] = ["0", "1"]
                else:
                    try:
                        [float(x) for x in unique_values]
                        numeric_cols.append(idx)
                    except ValueError:
                        categorical_cols.append(idx)
                        x_category_names[col] = sorted(list(map(str, unique_values)))

            # Handle output variable (target column)
            y_column_type = {"numeric": [], "categorical": []}
            y_category_names = {}
            unique_values = set(df[target_column].unique())

            if target_column == "action" or not all(
                str(x).isdigit() for x in unique_values
            ):
                # Actions or non-numeric values are categorical
                y_column_type["categorical"].append(0)
                y_category_names[target_column] = sorted(list(map(str, unique_values)))
            else:
                # Numeric memory values
                y_column_type["numeric"].append(0)

            return {
                "x_column_types": {
                    "numeric": numeric_cols,
                    "categorical": categorical_cols,
                },
                "y_column_types": y_column_type,
                "x_column_names": all_columns,
                #                 # "x_category_names": x_category_names,
                "y_column_names": [target_column],
                # "y_category_names": [y_category_names], unneeded
            }

        # Save action data and config
        action_config = create_config(action_df_filtered, "action")
        with open(action_file, "w") as f:
            f.write("#NON-PERMISSIVE\n")
            f.write(f"#BEGIN {num_inputs} 1\n")
            action_df_filtered.drop(columns=["memory"]).to_csv(
                f,
                index=False,
                header=False,
                columns=list(self.observation_keys) + ["action"],
            )

        action_config_path = os.path.join(
            memory_dir, f"{memory_value}_action_data_config.json"
        )
        with open(action_config_path, "w") as f:
            json.dump(action_config, f, indent=2)

        # Save memory transition data and config
        memory_config = create_config(memory_df_filtered, "next_memory")
        with open(memory_file, "w") as f:
            f.write("#NON-PERMISSIVE\n")
            f.write(f"#BEGIN {num_inputs} 1\n")
            memory_df_filtered.drop(columns=["memory"]).to_csv(
                f,
                index=False,
                header=False,
                columns=list(self.observation_keys) + ["next_memory"],
            )

        memory_config_path = os.path.join(
            memory_dir, f"{memory_value}_memory_data_config.json"
        )
        with open(memory_config_path, "w") as f:
            json.dump(memory_config, f, indent=2)

        return action_file, memory_file

    def run_dtcontrol(self):
        """
        Runs dtControl on the generated CSV files for each memory value.
        """
        # Get unique memory values from both action and memory data
        action_df = self.get_action_dataframe()
        memory_df = self.get_memory_dataframe()
        memory_values = sorted(
            set(action_df["memory"].unique()) | set(memory_df["memory"].unique())
        )

        benchmark_file = os.path.join("decision_trees", "benchmark.json")
        output_dir = os.path.join("decision_trees")

        for memory_value in memory_values:
            try:
                action_file, memory_file = self.save_csv_files(memory_value)

                print(f"\nProcessing trees for memory value {memory_value}")

                # Run dtControl for action selection
                subprocess.run(
                    [
                        self.dtcontrol_path,
                        "--input",
                        action_file,
                        "--use-preset",
                        "default",
                        "--output",
                        output_dir,
                        "--benchmark-file",
                        benchmark_file,
                        "--rerun",
                    ],
                    check=True,
                )

                # Run dtControl for memory transition
                subprocess.run(
                    [
                        self.dtcontrol_path,
                        "--input",
                        memory_file,
                        "--use-preset",
                        "default",
                        "--output",
                        output_dir,
                        "--benchmark-file",
                        benchmark_file,
                        "--rerun",
                    ],
                    check=True,
                )

            except subprocess.CalledProcessError as e:
                print(f"dtControl failed for memory {memory_value} with error: {e}")
                continue


